good_example:
class MiActivity {
    val adaptador: Adaptador by lazy { crearAdaptador() } // se inicializa la primera vez que se usa, nunca 'uninitialized'
    fun onResume() {
        adaptador.refrescar()
    }
}

bad_example:
class Formulario {
    var email: String? = null
    fun validar() {
        if (email != null) {
            enviar(email.length) // error de compilacion: smart cast no aplica a 'var' de clase
        }
    }
}

good_example:
class Formulario {
    var email: String? = null
    fun validar() {
        val emailLocal = email
        if (emailLocal != null) {
            enviar(emailLocal.length) // ok, emailLocal es una val local, smart-cast valido
        }
    }
}

bad_example:
fun cargarDatos() {
    GlobalScope.launch {
        val datos = api.fetch() // si tira excepcion, crashea el proceso; y la coroutine no se cancela nunca al cerrar la pantalla
        mostrar(datos)
    }
}

good_example:
fun cargarDatos(scope: CoroutineScope) {
    scope.launch(CoroutineExceptionHandler { _, e -> logError(e) }) {
        val datos = api.fetch()
        mostrar(datos)
    } // atado al scope de la pantalla/viewmodel: se cancela solo cuando corresponde
}

